public function test_paid_monthly_package_shows_monthly_due_soon_not_unpaid(): void
{
    $token = $this->createDirectorToken([1]);
    $student = $this->makeStudent(1);
    $t1 = $this->makeTeacher();
    $t2 = $this->makeTeacher();
    $this->ensureSubjects();

